test('addLine and removeLine: chain operations', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result1.ok, true);

  const result2 = addLine(result1.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result2.ok, true);
  assert.equal(result2.value.lines.length, 2);

  const result3 = addLine(result2.value, { sku: 'COPY-HOUR', qty: 2 });
  assert.equal(result3.ok, true);
  assert.equal(result3.value.lines.length, 3);

  const result4 = removeLine(result3.value, 'DES-HOUR');
  assert.equal(result4.ok, true);
  assert.equal(result4.value.lines.length, 2);
  assert.equal(result4.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(result4.value.lines[1].sku, 'COPY-HOUR');
});

